---@class SShopPkHandler : SPacketHandlers
local ShopPkHandler = T(Global, "PacketHandlers")
---@type SShopMgr
local SShopMgr = T(Global, "SShopMgr")
---@type PidPacketSender : SPidPacketSender
local PidPacketSender = T(Global, "PidPacketSender")

function ShopPkHandler:onPlayerRecycleShop(packet)
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(self.userId) and self:getPermissionRole() ~= Define.CustomGamePermissionRole.Admin then
        return
    end
    if not self:checkCanAddItem(Define.NpcItemId, 0, 1) then
        PidPacketSender:sendShopTip(self.userId, "gui.shop.is.full.inventory")
        return
    end
    self:addItem(Define.NpcItemId, 1)
    SShopMgr:removeShop(packet.id)
end

function ShopPkHandler:onEditShop(packet)
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(self.userId) and self:getPermissionRole() ~= Define.CustomGamePermissionRole.Admin then
        return
    end
    local shop = SShopMgr:getShop(packet.shopId)
    if shop then
        shop:saveShop(packet.goodsInfo, packet.name)
    end
end

function ShopPkHandler:onBuyGoods(packet)
    local shop = SShopMgr:getShop(packet.shopId)
    if shop then
        shop:onBuyGoods(self.userId, packet.goods)
    end
end

return ShopPkHandler